import type { MenuSteps } from "./menuStepsTypes";

export const DESIGN_STEPS: MenuSteps = {
  siteDesigner: [
    { target: "sd-view", placement: "bottom",
      t: ["Two views of one design", "Dos vistas de un mismo diseño", "Zwei Ansichten eines Entwurfs", "Deux vues d'un même plan", "Due viste di un solo progetto", "1つの設計を2つの視点で", "同一设计的两种视图", "Duas vistas de um só desenho"],
      b: ["The design has a flat 2D plan, good for drawing exact shapes, and a 3D view you can turn around, good for heights and for seeing the field of view of cameras and radars. They are the same design: what you draw in one appears in the other. Start from a blank site or from \"Start from an example\" and change it. Floors are chosen in the floor selector; \"Add a floor\" puts one above.",
        "El diseño tiene un plano 2D plano, bueno para dibujar formas exactas, y una vista 3D que puedes girar, buena para las alturas y para ver el campo de visión de cámaras y radares. Son el mismo diseño: lo que dibujas en una aparece en la otra. Empieza con un sitio en blanco o con \"Empezar desde un ejemplo\" y cámbialo. Las plantas se eligen en el selector de planta; \"Añadir una planta\" pone una encima.",
        "Der Entwurf hat einen flachen 2D-Plan, gut für exakte Formen, und eine drehbare 3D-Ansicht, gut für Höhen und für das Sichtfeld von Kameras und Radaren. Es ist derselbe Entwurf: Was Sie in einer zeichnen, erscheint in der anderen. Beginnen Sie mit einem leeren Standort oder \"Mit einem Beispiel beginnen\" und ändern Sie es. Etagen wählen Sie im Etagenwähler; \"Etage hinzufügen\" setzt eine darüber.",
        "Le plan a une vue 2D à plat, idéale pour dessiner des formes exactes, et une vue 3D que l'on fait tourner, idéale pour les hauteurs et le champ de vision des caméras et radars. C'est le même plan : ce que vous dessinez dans l'une apparaît dans l'autre. Partez d'un site vierge ou de « Partir d'un exemple » et modifiez-le. Les étages se choisissent dans le sélecteur d'étage ; « Ajouter un étage » en met un au-dessus.",
        "Il progetto ha una pianta 2D piatta, ottima per disegnare forme esatte, e una vista 3D che puoi ruotare, ottima per le altezze e per vedere il campo visivo di telecamere e radar. È lo stesso progetto: ciò che disegni in una appare nell'altra. Parti da un sito vuoto o da \"Parti da un esempio\" e modificalo. I piani si scelgono nel selettore dei piani; \"Aggiungi un piano\" ne mette uno sopra.",
        "設計には、正確な形を描くのに向く平面の2D図と、高さやカメラ・レーダーの視野を見るのに向く、回転できる3Dビューがあります。同じ設計なので、一方で描いたものは他方にも現れます。空のサイトか「例から始める」で始めて編集しましょう。階は階セレクターで選び、「階を追加」で上に1階増やします。",
        "设计有平面的 2D 图（适合绘制精确形状）和可旋转的 3D 视图（适合看高度以及摄像头、雷达的视野）。两者是同一份设计：在一边画的内容会出现在另一边。可以从空白场地或“从示例开始”入手再修改。楼层在楼层选择器中选择；“添加楼层”会在上方加一层。",
        "O desenho tem uma planta 2D plana, boa para desenhar formas exatas, e uma vista 3D que pode rodar, boa para as alturas e para ver o campo de visão de câmaras e radares. É o mesmo desenho: o que desenhar numa aparece na outra. Comece com um local em branco ou com \"Começar por um exemplo\" e altere-o. Os pisos escolhem-se no seletor de pisos; \"Adicionar um piso\" põe um por cima."] },
    { target: "sd-canvas", placement: "left",
      t: ["Draw the terrain, the buildings and the objects", "Dibuja el terreno, los edificios y los objetos", "Gelände, Gebäude und Objekte zeichnen", "Dessinez le terrain, les bâtiments et les objets", "Disegna il terreno, gli edifici e gli oggetti", "敷地・建物・オブジェクトを描く", "绘制地块、建筑和物体", "Desenhe o terreno, os edifícios e os objetos"],
      b: ["The floating toolbox on the canvas holds the tools: draw the terrain (a rectangle or any shape, corner by corner) and the buildings, then add doors, windows, arches, garage doors, roofs (with gutters, chimneys and solar panels), terraces, pools, fences, trees, paths, roads, lamps and masts. Type a length and press Enter for exact sides; the grid and the snap to the grid and to walls help. You can drag the toolbox by its title and fold it.",
        "La caja de herramientas flotante del lienzo reúne las herramientas: dibuja el terreno (un rectángulo o cualquier forma, esquina a esquina) y los edificios; luego añade puertas, ventanas, arcos, puertas de garaje, tejados (con canalones, chimeneas y paneles solares), terrazas, piscinas, vallas, árboles, caminos, carreteras, farolas y mástiles. Escribe una longitud y pulsa Intro para lados exactos; la cuadrícula y el ajuste a cuadrícula y a paredes ayudan. Puedes arrastrar la caja por su título y plegarla.",
        "Die schwebende Werkzeugkiste auf der Zeichenfläche enthält die Werkzeuge: Gelände zeichnen (Rechteck oder beliebige Form, Ecke für Ecke) und Gebäude, dann Türen, Fenster, Bögen, Garagentore, Dächer (mit Dachrinnen, Schornsteinen und Solarmodulen), Terrassen, Pools, Zäune, Bäume, Wege, Straßen, Lampen und Masten. Tippen Sie eine Länge und drücken Sie Enter für exakte Seiten; Raster und Einrasten an Raster und Wänden helfen. Die Kiste lässt sich am Titel ziehen und einklappen.",
        "La boîte à outils flottante du canevas contient les outils : tracez le terrain (un rectangle ou une forme libre, coin par coin) et les bâtiments, puis ajoutez portes, fenêtres, arches, portes de garage, toits (avec gouttières, cheminées et panneaux solaires), terrasses, piscines, clôtures, arbres, chemins, routes, lampadaires et mâts. Tapez une longueur et appuyez sur Entrée pour des côtés exacts ; la grille et l'accrochage à la grille et aux murs aident. La boîte se déplace par son titre et se replie.",
        "La cassetta degli strumenti fluttuante sul disegno contiene gli strumenti: disegna il terreno (un rettangolo o una forma libera, angolo per angolo) e gli edifici, poi aggiungi porte, finestre, archi, porte da garage, tetti (con grondaie, camini e pannelli solari), terrazze, piscine, recinzioni, alberi, sentieri, strade, lampioni e pali. Scrivi una lunghezza e premi Invio per lati esatti; la griglia e l'aggancio alla griglia e ai muri aiutano. La cassetta si trascina dal titolo e si ripiega.",
        "キャンバス上の浮動ツールボックスに道具が入っています。敷地（四角形または自由な形を角ごとに）と建物を描き、ドア、窓、アーチ、ガレージドア、屋根（雨どい・煙突・太陽光パネル付き）、テラス、プール、フェンス、樹木、小道、道路、街灯、マストを追加します。長さを入力してEnterを押すと辺を正確に指定でき、グリッドやグリッド／壁へのスナップも役立ちます。ツールボックスはタイトルをドラッグして移動、折りたたみもできます。",
        "画布上的浮动工具箱收纳了各种工具：绘制地块（矩形或任意形状，逐个角点）和建筑，然后添加门、窗、拱门、车库门、屋顶（含排水槽、烟囱和太阳能板）、露台、泳池、围栏、树木、小路、道路、路灯和灯杆。输入长度并按 Enter 可得到精确的边长；网格以及对网格和墙体的吸附也很有帮助。工具箱可拖动标题移动，也可折叠。",
        "A caixa de ferramentas flutuante sobre o desenho reúne as ferramentas: desenhe o terreno (um retângulo ou qualquer forma, canto a canto) e os edifícios, depois acrescente portas, janelas, arcos, portões de garagem, telhados (com caleiras, chaminés e painéis solares), terraços, piscinas, vedações, árvores, caminhos, estradas, candeeiros e mastros. Escreva um comprimento e prima Enter para lados exatos; a grelha e o ajuste à grelha e às paredes ajudam. Arraste a caixa pelo título e dobre-a."] },
    { target: "sd-canvas", placement: "left",
      t: ["Place the real equipment", "Coloca el equipo real", "Die echte Ausrüstung platzieren", "Placez l'équipement réel", "Posiziona le apparecchiature reali", "実際の機器を配置する", "放置真实设备", "Coloque o equipamento real"],
      b: ["Cameras are created in Configuration and only get their position here; radars take theirs with the round handle to turn them; devices go where they really are. In 3D the field of view of cameras and radars is drawn, and the \"Ignore zones\" of the radars are set here too. What you place here is what the Overview map, the Radar map and the alarms show, so spend a minute getting each position and direction right.",
        "Las cámaras se crean en Configuración y aquí solo reciben su posición; los radares toman la suya con el tirador redondo para girarlos; los dispositivos van donde están de verdad. En 3D se dibuja el campo de visión de cámaras y radares, y las \"Zonas ignoradas\" de los radares también se fijan aquí. Lo que coloques aquí es lo que muestran el mapa de Resumen, el mapa de Radar y las alarmas, así que dedica un minuto a acertar cada posición y dirección.",
        "Kameras werden in der Konfiguration angelegt und erhalten hier nur ihre Position; Radare bekommen ihre mit dem runden Griff zum Drehen; Geräte kommen dorthin, wo sie wirklich stehen. In 3D wird das Sichtfeld von Kameras und Radaren gezeichnet, und die \"Ignorierzonen\" der Radare legen Sie ebenfalls hier fest. Was Sie hier platzieren, zeigen die Karte der Übersicht, die Radarkarte und die Alarme - nehmen Sie sich eine Minute, um Position und Richtung zu treffen.",
        "Les caméras se créent dans Configuration et reçoivent seulement leur position ici ; les radars prennent la leur avec la poignée ronde pour les orienter ; les appareils vont là où ils sont vraiment. En 3D le champ de vision des caméras et radars est dessiné, et les « zones ignorées » des radars se règlent aussi ici. Ce que vous placez ici est ce que montrent la carte de l'Aperçu, la carte Radar et les alarmes : prenez une minute pour bien régler chaque position et direction.",
        "Le telecamere si creano in Configurazione e qui ricevono solo la posizione; i radar prendono la loro con la maniglia rotonda per girarli; i dispositivi vanno dove sono davvero. In 3D si disegna il campo visivo di telecamere e radar, e anche le \"zone ignorate\" dei radar si impostano qui. Ciò che posizioni qui è ciò che mostrano la mappa di Panoramica, la mappa Radar e gli allarmi: dedica un minuto a centrare ogni posizione e direzione.",
        "カメラは「設定」で作成し、ここでは位置だけを決めます。レーダーは丸いハンドルで向きを回して配置し、デバイスは実際にある場所に置きます。3Dではカメラとレーダーの視野が描かれ、レーダーの「無視ゾーン」もここで設定できます。ここで置いたものが、概要の地図・レーダーの地図・アラームの表示になるので、位置と向きは丁寧に合わせましょう。",
        "摄像头在“配置”中创建，这里只需设置位置；雷达用圆形手柄转动朝向；设备则放在真实所在的位置。3D 中会绘制摄像头和雷达的视野，雷达的“忽略区”也在这里设置。你在这里放置的内容就是“概览”地图、“雷达”地图和报警所显示的内容，所以请花一分钟把每个位置和方向放准。",
        "As câmaras criam-se em Configuração e aqui só recebem a posição; os radares recebem a sua com a pega redonda para os rodar; os dispositivos vão onde estão de facto. Em 3D desenha-se o campo de visão de câmaras e radares, e as \"zonas ignoradas\" dos radares também se definem aqui. O que colocar aqui é o que mostram o mapa de Resumo, o mapa de Radar e os alarmes, por isso dedique um minuto a acertar cada posição e direção."] },
    { target: "sd-inspector", placement: "left",
      t: ["The properties of what you select", "Las propiedades de lo que seleccionas", "Die Eigenschaften der Auswahl", "Les propriétés de la sélection", "Le proprietà della selezione", "選択したもののプロパティ", "所选内容的属性", "As propriedades do que seleciona"],
      b: ["The panel on the right changes with the selection: the size, height and finish of a building, the properties of a door or a lamp, the settings of a camera or a radar. Here a rectangular building can become a \"Block of flats\" (floors, corridor, flats, stairs, lift, street door with video intercom, alarm panel in the hall), and objects can be tied to the real thing: a video intercom to a camera, an alarm panel to a real panel, a stair light to a device. A tied object shows what the thing says now and a button opens that menu.",
        "El panel de la derecha cambia con la selección: el tamaño, la altura y el acabado de un edificio, las propiedades de una puerta o una farola, los ajustes de una cámara o un radar. Aquí un edificio rectangular puede convertirse en un \"Bloque de pisos\" (plantas, pasillo, viviendas, escaleras, ascensor, portal con videoportero, central de alarma en el hall), y los objetos pueden ligarse a lo real: un videoportero a una cámara, una central de alarma a una central real, una luz de escalera a un dispositivo. Un objeto ligado muestra lo que dice la cosa ahora y un botón abre ese menú.",
        "Das Feld rechts ändert sich mit der Auswahl: Größe, Höhe und Ausführung eines Gebäudes, Eigenschaften einer Tür oder Lampe, Einstellungen einer Kamera oder eines Radars. Hier kann ein rechteckiges Gebäude zum \"Wohnblock\" werden (Etagen, Flur, Wohnungen, Treppen, Aufzug, Haustür mit Video-Sprechanlage, Alarmzentrale in der Halle), und Objekte lassen sich mit dem Echten verknüpfen: eine Video-Sprechanlage mit einer Kamera, eine Alarmzentrale mit einer echten Zentrale, ein Treppenlicht mit einem Gerät. Ein verknüpftes Objekt zeigt, was das Ding jetzt meldet, und ein Knopf öffnet dieses Menü.",
        "Le panneau de droite change avec la sélection : taille, hauteur et finition d'un bâtiment, propriétés d'une porte ou d'un lampadaire, réglages d'une caméra ou d'un radar. Ici un bâtiment rectangulaire peut devenir un « Immeuble » (étages, couloir, appartements, escaliers, ascenseur, porte de rue avec visiophone, centrale d'alarme dans le hall), et les objets peuvent être liés au réel : un visiophone à une caméra, une centrale d'alarme à une vraie centrale, une lumière d'escalier à un appareil. Un objet lié montre ce que dit la chose maintenant et un bouton ouvre ce menu.",
        "Il pannello a destra cambia con la selezione: dimensione, altezza e finitura di un edificio, proprietà di una porta o di un lampione, impostazioni di una telecamera o di un radar. Qui un edificio rettangolare può diventare un \"Condominio\" (piani, corridoio, appartamenti, scale, ascensore, portone con videocitofono, centrale di allarme nell'atrio), e gli oggetti si possono legare al reale: un videocitofono a una telecamera, una centrale di allarme a una centrale vera, una luce delle scale a un dispositivo. Un oggetto legato mostra ciò che dice la cosa adesso e un pulsante apre quel menu.",
        "右のパネルは選択に応じて変わります：建物の大きさ・高さ・仕上げ、ドアや街灯の属性、カメラやレーダーの設定など。ここで長方形の建物を「集合住宅」にでき（各階、廊下、住戸、階段、エレベーター、ビデオインターホン付きの玄関、ホールの警報制御盤）、オブジェクトを実物に紐付けられます：ビデオインターホンをカメラに、警報制御盤を実際の制御盤に、階段灯をデバイスに。紐付けたオブジェクトは今の状態を表示し、ボタンでそのメニューを開けます。",
        "右侧面板随选择内容变化：建筑的尺寸、高度和外观，门或路灯的属性，摄像头或雷达的设置。在这里可以把矩形建筑变成“公寓楼”（楼层、走廊、住户、楼梯、电梯、带可视对讲的街门、大厅里的报警主机），还可以把物体与真实设备关联：可视对讲关联摄像头，报警主机关联真实主机，楼梯灯关联设备。已关联的物体会显示该设备当前的状态，按钮可打开对应菜单。",
        "O painel da direita muda com a seleção: o tamanho, a altura e o acabamento de um edifício, as propriedades de uma porta ou candeeiro, as definições de uma câmara ou de um radar. Aqui um edifício retangular pode tornar-se um \"Prédio de apartamentos\" (pisos, corredor, frações, escadas, elevador, porta da rua com videoporteiro, central de alarme no átrio), e os objetos podem ligar-se ao real: um videoporteiro a uma câmara, uma central de alarme a uma central real, uma luz de escada a um dispositivo. Um objeto ligado mostra o que a coisa diz agora e um botão abre esse menu."] },
    { target: "sd-actions", placement: "bottom",
      t: ["Undo, versions and saving", "Deshacer, versiones y guardado", "Rückgängig, Versionen und Speichern", "Annuler, versions et enregistrement", "Annulla, versioni e salvataggio", "元に戻す・バージョン・保存", "撤销、版本与保存", "Desfazer, versões e guardar"],
      b: ["Undo and redo (Ctrl+Z and Ctrl+Y) walk through your changes. \"Versions\" shows the earlier saved versions of the design and lets you go back to one, so an experiment is never a risk. Save stores the design on the server, so every browser and the phone see the same. \"Export site JSON\" downloads the whole design as a file. In 3D, the left button selects and moves, the right or middle button pans, the wheel zooms and Shift while dragging changes an object's height.",
        "Deshacer y rehacer (Ctrl+Z y Ctrl+Y) recorren tus cambios. \"Versiones\" muestra las versiones guardadas antes del diseño y deja volver a una, así que un experimento nunca es un riesgo. Guardar almacena el diseño en el servidor, así que todos los navegadores y el móvil ven lo mismo. \"Exportar JSON del sitio\" descarga todo el diseño como archivo. En 3D, el botón izquierdo selecciona y mueve, el derecho o el central desplaza, la rueda hace zoom y Mayús al arrastrar cambia la altura de un objeto.",
        "Rückgängig und Wiederholen (Strg+Z und Strg+Y) gehen durch Ihre Änderungen. \"Versionen\" zeigt frühere gespeicherte Versionen des Entwurfs und lässt Sie zu einer zurückkehren - ein Experiment ist nie ein Risiko. Speichern legt den Entwurf auf dem Server ab, sodass jeder Browser und das Handy dasselbe sehen. \"Standort-JSON exportieren\" lädt den ganzen Entwurf als Datei herunter. In 3D wählt und verschiebt die linke Taste, die rechte oder mittlere verschiebt die Ansicht, das Rad zoomt, und Umschalt beim Ziehen ändert die Höhe eines Objekts.",
        "Annuler et rétablir (Ctrl+Z et Ctrl+Y) parcourent vos changements. « Versions » montre les versions enregistrées du plan et permet de revenir à l'une d'elles : un essai n'est jamais un risque. Enregistrer stocke le plan sur le serveur, donc tous les navigateurs et le téléphone voient la même chose. « Exporter le JSON du site » télécharge tout le plan en fichier. En 3D, le bouton gauche sélectionne et déplace, le droit ou le milieu fait glisser la vue, la molette zoome et Maj en glissant change la hauteur d'un objet.",
        "Annulla e ripeti (Ctrl+Z e Ctrl+Y) ripercorrono le tue modifiche. \"Versioni\" mostra le versioni salvate in precedenza del progetto e permette di tornare a una, così un esperimento non è mai un rischio. Salva memorizza il progetto sul server, quindi ogni browser e il telefono vedono lo stesso. \"Esporta JSON del sito\" scarica tutto il progetto come file. In 3D, il tasto sinistro seleziona e sposta, il destro o centrale sposta la vista, la rotellina fa zoom e Maiusc trascinando cambia l'altezza di un oggetto.",
        "元に戻す／やり直し（Ctrl+Z、Ctrl+Y）で変更を行き来できます。「バージョン」では過去に保存した設計を一覧し、戻せるので、試行錯誤にリスクはありません。保存で設計がサーバーに保存され、どのブラウザーやスマホでも同じものが見えます。「サイトJSONを書き出す」で設計全体をファイルにできます。3Dでは左ボタンで選択・移動、右または中ボタンで平行移動、ホイールでズーム、Shiftを押しながらドラッグでオブジェクトの高さを変えます。",
        "撤销和重做（Ctrl+Z 和 Ctrl+Y）可在你的修改间来回。“版本”会显示设计之前保存的版本并可回到其中一个，所以试验没有风险。保存会把设计存到服务器，所有浏览器和手机看到的都一样。“导出场地 JSON”会把整个设计下载为文件。在 3D 中，左键选择并移动，右键或中键平移，滚轮缩放，拖动时按住 Shift 可改变物体高度。",
        "Desfazer e refazer (Ctrl+Z e Ctrl+Y) percorrem as suas alterações. \"Versões\" mostra as versões guardadas antes do desenho e deixa voltar a uma, por isso uma experiência nunca é um risco. Guardar grava o desenho no servidor, por isso todos os navegadores e o telemóvel veem o mesmo. \"Exportar JSON do local\" descarrega todo o desenho como ficheiro. Em 3D, o botão esquerdo seleciona e move, o direito ou o do meio desloca a vista, a roda faz zoom e Maiús ao arrastar muda a altura de um objeto."] },
  ],
  alarmDesigner: [
    { target: "ad-palette", placement: "right",
      t: ["The palette: panels, sensors, sirens and more", "La paleta: centrales, sensores, sirenas y más", "Die Palette: Zentralen, Sensoren, Sirenen und mehr", "La palette : centrales, capteurs, sirènes et plus", "La tavolozza: centrali, sensori, sirene e altro", "パレット：制御盤・センサー・サイレンなど", "元件库：主机、传感器、警笛等", "A paleta: centrais, sensores, sirenes e mais"],
      b: ["Elements are grouped by category: the panels (alarm panel, zone expanders, communicator), the sensors (door and window contacts, motion and dual-technology detectors, outdoor beams, glass-break and vibration, smoke, heat, CO, gas and flood detectors, panic buttons, tamper switches), sirens and outputs, keypads, card readers, key fobs and touch panels, and the supply (power supply and backup battery). Pick one and click on the drawing to place it; you can also drag it from the palette.",
        "Los elementos se agrupan por categoría: las centrales (central de alarma, expansores de zona, comunicador), los sensores (contactos de puerta y ventana, detectores de movimiento y de doble tecnología, barreras exteriores, rotura de cristal y vibración, humo, calor, CO, gas e inundación, botones de pánico, interruptores antisabotaje), sirenas y salidas, teclados, lectores de tarjeta, mandos y paneles táctiles, y la alimentación (fuente y batería de respaldo). Elige uno y haz clic en el dibujo para colocarlo; también puedes arrastrarlo desde la paleta.",
        "Die Elemente sind nach Kategorien gruppiert: die Zentralen (Alarmzentrale, Zonenerweiterungen, Kommunikator), die Sensoren (Tür- und Fensterkontakte, Bewegungs- und Dualmelder, Außenschranken, Glasbruch und Vibration, Rauch, Hitze, CO, Gas und Wasser, Panikknöpfe, Sabotagekontakte), Sirenen und Ausgänge, Bedienteile, Kartenleser, Handsender und Touch-Panels sowie die Versorgung (Netzteil und Notakku). Wählen Sie eines und klicken Sie in die Zeichnung, um es zu platzieren; Sie können es auch aus der Palette ziehen.",
        "Les éléments sont groupés par catégorie : les centrales (centrale d'alarme, extensions de zones, communicateur), les capteurs (contacts de porte et fenêtre, détecteurs de mouvement et double technologie, barrières extérieures, bris de vitre et vibration, fumée, chaleur, CO, gaz et inondation, boutons panique, contacts d'autoprotection), sirènes et sorties, claviers, lecteurs de cartes, télécommandes et écrans tactiles, et l'alimentation (bloc et batterie de secours). Choisissez-en un et cliquez dans le dessin pour le placer ; vous pouvez aussi le glisser depuis la palette.",
        "Gli elementi sono raggruppati per categoria: le centrali (centrale di allarme, espansioni di zona, comunicatore), i sensori (contatti porta e finestra, rilevatori di movimento e doppia tecnologia, barriere esterne, rottura vetri e vibrazione, fumo, calore, CO, gas e allagamento, pulsanti di panico, interruttori antimanomissione), sirene e uscite, tastiere, lettori di tessere, telecomandi e pannelli touch, e l'alimentazione (alimentatore e batteria di riserva). Scegline uno e clicca sul disegno per posizionarlo; puoi anche trascinarlo dalla tavolozza.",
        "要素はカテゴリー別に並びます：制御盤（警報制御盤、ゾーン拡張、通報装置）、センサー（ドア・窓の接点、人感・デュアル検知器、屋外ビーム、ガラス破壊・振動、煙・熱・CO・ガス・浸水検知器、非常ボタン、改ざんスイッチ）、サイレンと出力、キーパッド、カードリーダー、リモコン、タッチパネル、電源（電源装置とバックアップ電池）。1つ選んで図面をクリックして配置します。パレットからドラッグもできます。",
        "元件按类别分组：主机（报警主机、分区扩展器、通信器）、传感器（门窗磁、移动与双鉴探测器、室外对射、玻璃破碎和震动、烟雾、热、CO、燃气和水浸探测器、紧急按钮、防拆开关）、警笛与输出、键盘、读卡器、遥控器和触摸屏，以及供电（电源和备用电池）。选一个再点击图纸放置；也可从元件库拖入。",
        "Os elementos agrupam-se por categoria: as centrais (central de alarme, expansores de zona, comunicador), os sensores (contactos de porta e janela, detetores de movimento e de dupla tecnologia, barreiras exteriores, quebra de vidro e vibração, fumo, calor, CO, gás e inundação, botões de pânico, interruptores antissabotagem), sirenes e saídas, teclados, leitores de cartões, comandos e painéis táteis, e a alimentação (fonte e bateria de reserva). Escolha um e clique no desenho para o colocar; também o pode arrastar da paleta."] },
    { target: "ad-canvas", placement: "left",
      t: ["Links: five kinds of connection", "Enlaces: cinco tipos de conexión", "Verbindungen: fünf Arten", "Liaisons : cinq types de connexion", "Collegamenti: cinque tipi di connessione", "リンク：5種類の接続", "连线：五种连接", "Ligações: cinco tipos de ligação"],
      b: ["With the Link tool, click one port and then the other to join them. There are five kinds: the wired loop (a sensor to a loop of the panel), the radio link, the siren output, the data bus (keypads and expanders) and the supply. A sensor reaches its panel by its wire or by radio, not by both. Rotate (R) turns the selected element and \"Change the kind\" swaps it for another of the same group keeping its links. A frame groups elements of a room or a floor.",
        "Con la herramienta Enlace, haz clic en un puerto y luego en el otro para unirlos. Hay cinco tipos: el lazo cableado (un sensor a un lazo de la central), el enlace por radio, la salida de sirena, el bus de datos (teclados y expansores) y la alimentación. Un sensor llega a su central por su cable o por radio, no por ambos. Girar (R) gira el elemento seleccionado y \"Cambiar el tipo\" lo sustituye por otro del mismo grupo conservando sus enlaces. Un marco agrupa los elementos de una habitación o de una planta.",
        "Mit dem Verbindungswerkzeug klicken Sie erst einen Port, dann den anderen an. Es gibt fünf Arten: die verdrahtete Schleife (ein Sensor an einer Schleife der Zentrale), die Funkverbindung, den Sirenenausgang, den Datenbus (Bedienteile und Erweiterungen) und die Versorgung. Ein Sensor erreicht seine Zentrale per Draht oder per Funk, nicht beides. Drehen (R) dreht das gewählte Element, \"Art ändern\" tauscht es gegen ein anderes derselben Gruppe und behält die Verbindungen. Ein Rahmen fasst die Elemente eines Raums oder einer Etage zusammen.",
        "Avec l'outil Liaison, cliquez sur un port puis sur l'autre pour les joindre. Il y a cinq types : la boucle filaire (un capteur à une boucle de la centrale), la liaison radio, la sortie sirène, le bus de données (claviers et extensions) et l'alimentation. Un capteur atteint sa centrale par son fil ou par radio, pas les deux. Pivoter (R) tourne l'élément sélectionné et « Changer le type » le remplace par un autre du même groupe en gardant ses liaisons. Un cadre regroupe les éléments d'une pièce ou d'un étage.",
        "Con lo strumento Collegamento, clicca su una porta e poi sull'altra per unirle. Ci sono cinque tipi: l'anello cablato (un sensore a un anello della centrale), il collegamento radio, l'uscita sirena, il bus dati (tastiere ed espansioni) e l'alimentazione. Un sensore raggiunge la sua centrale via cavo o via radio, non entrambi. Ruota (R) gira l'elemento selezionato e \"Cambia il tipo\" lo sostituisce con un altro dello stesso gruppo mantenendo i collegamenti. Un riquadro raggruppa gli elementi di una stanza o di un piano.",
        "リンクツールで、1つのポートをクリックしてからもう1つをクリックすると接続されます。種類は5つ：有線ループ（センサーから制御盤のループ）、無線リンク、サイレン出力、データバス（キーパッドと拡張）、電源。センサーは有線か無線のどちらかで制御盤につながり、両方は不可です。回転（R）で選択要素を回し、「種類を変更」で同じグループの別の要素に置き換えます（リンクは維持）。フレームで部屋や階の要素をまとめます。",
        "使用连线工具，先点一个端口再点另一个即可相连。共有五种连线：有线回路（传感器到主机的某个回路）、无线连接、警笛输出、数据总线（键盘和扩展器）和供电。传感器通过有线或无线接到主机，不能同时使用两种。旋转（R）转动所选元件，“更换类型”会换成同组的另一种并保留连线。框用于把一个房间或楼层的元件归为一组。",
        "Com a ferramenta Ligação, clique numa porta e depois na outra para as unir. Há cinco tipos: o laço com fios (um sensor a um laço da central), a ligação por rádio, a saída de sirene, o barramento de dados (teclados e expansores) e a alimentação. Um sensor chega à sua central por fio ou por rádio, não pelos dois. Rodar (R) roda o elemento selecionado e \"Mudar o tipo\" troca-o por outro do mesmo grupo mantendo as ligações. Uma moldura agrupa os elementos de uma divisão ou de um piso."] },
    { target: "ad-toolbar", placement: "bottom",
      t: ["The toolbar: edit, design and files", "La barra: editar, diseño y archivos", "Die Leiste: Bearbeiten, Entwurf und Dateien", "La barre : modifier, conception et fichiers", "La barra: modifica, progetto e file", "ツールバー：編集・設計・ファイル", "工具栏：编辑、设计与文件", "A barra: editar, desenho e ficheiros"],
      b: ["Edit: Select, Link, Frame, undo, redo and \"fit the drawing in view\". Design: New starts an empty drawing, \"A typical house\" loads an example, \"Draw what the panels have\" adds every real panel and zone that is not yet in the drawing (each sensor guessed from the name of its zone), and Versions shows the earlier saved versions. Files: export the drawing as JSON or SVG and import one. Everything is kept on the server as you work.",
        "Editar: Seleccionar, Enlace, Marco, deshacer, rehacer y \"encajar el dibujo en la vista\". Diseño: Nuevo empieza un dibujo vacío, \"Una casa típica\" carga un ejemplo, \"Dibujar lo que tienen las centrales\" añade cada central y zona real que aún no está en el dibujo (cada sensor deducido del nombre de su zona), y Versiones muestra las versiones guardadas antes. Archivos: exporta el dibujo como JSON o SVG e importa uno. Todo se guarda en el servidor mientras trabajas.",
        "Bearbeiten: Auswählen, Verbindung, Rahmen, Rückgängig, Wiederholen und \"Zeichnung einpassen\". Entwurf: Neu beginnt eine leere Zeichnung, \"Ein typisches Haus\" lädt ein Beispiel, \"Zeichnen, was die Zentralen haben\" fügt jede echte Zentrale und Zone hinzu, die noch nicht in der Zeichnung ist (jeder Sensor aus dem Zonennamen erraten), und Versionen zeigt frühere Versionen. Dateien: Zeichnung als JSON oder SVG exportieren und eine importieren. Alles wird beim Arbeiten auf dem Server gespeichert.",
        "Modifier : Sélection, Liaison, Cadre, annuler, rétablir et « ajuster le dessin à la vue ». Conception : Nouveau démarre un dessin vide, « Une maison type » charge un exemple, « Dessiner ce que les centrales ont » ajoute chaque centrale et zone réelle absente du dessin (chaque capteur deviné d'après le nom de sa zone), et Versions montre les versions enregistrées. Fichiers : exporter le dessin en JSON ou SVG et en importer un. Tout est conservé sur le serveur pendant que vous travaillez.",
        "Modifica: Seleziona, Collegamento, Riquadro, annulla, ripeti e \"adatta il disegno alla vista\". Progetto: Nuovo avvia un disegno vuoto, \"Una casa tipica\" carica un esempio, \"Disegna ciò che hanno le centrali\" aggiunge ogni centrale e zona reale non ancora nel disegno (ogni sensore dedotto dal nome della sua zona), e Versioni mostra le versioni salvate prima. File: esporta il disegno in JSON o SVG e importane uno. Tutto è conservato sul server mentre lavori.",
        "編集：選択、リンク、フレーム、元に戻す、やり直し、「図面を表示に合わせる」。設計：「新規」で空の図面、「典型的な家」で例を読み込み、「制御盤の内容を描く」でまだ図面にない実際の制御盤とゾーンをすべて追加（センサーはゾーン名から推測）、「バージョン」で過去の保存版を表示。ファイル：図面をJSONまたはSVGで書き出し、取り込みもできます。作業中の内容はサーバーに保存されます。",
        "编辑：选择、连线、框、撤销、重做和“适应视图”。设计：“新建”开始空白图，“典型住宅”载入示例，“绘制主机已有内容”会添加图中还没有的每台真实主机和分区（传感器按分区名称推测），“版本”显示之前保存的版本。文件：把图导出为 JSON 或 SVG，也可导入一份。工作过程中的所有内容都保存在服务器上。",
        "Editar: Selecionar, Ligação, Moldura, desfazer, refazer e \"ajustar o desenho à vista\". Desenho: Novo começa um desenho vazio, \"Uma casa típica\" carrega um exemplo, \"Desenhar o que as centrais têm\" acrescenta cada central e zona real que ainda não está no desenho (cada sensor deduzido do nome da zona), e Versões mostra as versões guardadas antes. Ficheiros: exporte o desenho em JSON ou SVG e importe um. Tudo fica guardado no servidor enquanto trabalha."] },
    { target: "ad-modes", placement: "left",
      t: ["The Modes tab: Away, Home and Night", "La pestaña Modos: Fuera, En casa y Noche", "Der Reiter Modi: Abwesend, Zuhause und Nacht", "L'onglet Modes : Absent, À la maison et Nuit", "La scheda Modalità: Fuori casa, In casa e Notte", "「モード」タブ：外出・在宅・夜間", "“模式”标签页：离家、在家和夜间", "O separador Modos: Ausente, Em casa e Noite"],
      b: ["When the server has the arming modes, the side panel gets a Modes tab. Away defends everything; for Home and Night you tick the zones, sensors, radar nodes and cameras each one defends, and set their exit and entry delays. A timetable can change the mode by itself at a time of day. Smoke, gas, flood, panic and tamper guard in every mode, and editing arms nothing. Only an administrator saves.",
        "Cuando el servidor tiene los modos de armado, el panel lateral gana una pestaña Modos. Fuera defiende todo; para En casa y Noche marcas las zonas, sensores, nodos radar y cámaras que defiende cada uno, y ajustas sus retardos de salida y de entrada. Un horario puede cambiar el modo solo a una hora del día. Humo, gas, inundación, pánico y sabotaje vigilan en todos los modos, y editar no arma nada. Solo guarda un administrador.",
        "Hat der Server die Scharfschaltmodi, bekommt das Seitenpanel einen Reiter Modi. Abwesend schützt alles; für Zuhause und Nacht haken Sie die Zonen, Sensoren, Radarknoten und Kameras an, die jeder schützt, und stellen ihre Ausgangs- und Eingangsverzögerung ein. Ein Zeitplan kann den Modus zu einer Tageszeit selbstständig wechseln. Rauch, Gas, Wasser, Panik und Sabotage überwachen in jedem Modus, und Bearbeiten schaltet nichts scharf. Nur ein Administrator speichert.",
        "Quand le serveur a les modes d'armement, le panneau latéral gagne un onglet Modes. Absent protège tout ; pour À la maison et Nuit, vous cochez les zones, capteurs, nœuds radar et caméras que chacun protège, et réglez leurs délais de sortie et d'entrée. Une programmation peut changer le mode toute seule à une heure du jour. Fumée, gaz, inondation, panique et sabotage surveillent dans tous les modes, et modifier n'arme rien. Seul un administrateur enregistre.",
        "Quando il server ha le modalità di inserimento, il pannello laterale ottiene una scheda Modalità. Fuori casa protegge tutto; per In casa e Notte si spuntano le zone, i sensori, i nodi radar e le telecamere che ciascuna protegge, e se ne regolano i ritardi di uscita e di ingresso. Una programmazione può cambiare la modalità da sola a un'ora del giorno. Fumo, gas, allagamento, panico e manomissione vigilano in ogni modalità, e modificare non inserisce nulla. Salva solo un amministratore.",
        "サーバーが警戒モードに対応していると、サイドパネルに「モード」タブが加わります。「外出」はすべてを守ります。「在宅」と「夜間」では、それぞれが守るゾーン、センサー、レーダーノード、カメラにチェックを入れ、退出遅延と入口遅延を設定します。スケジュールで、決まった時刻にモードを自動で切り替えることもできます。煙、ガス、浸水、パニック、改ざんはどのモードでも常に監視し、編集しても警戒は行われません。保存できるのは管理者だけです。",
        "服务器支持布防模式时，侧边面板会多出“模式”标签页。“离家”保护所有内容；对“在家”和“夜间”，您勾选各自保护的区域、传感器、雷达节点和摄像头，并设置退出延时和进入延时。时间表可在一天中的某个时刻自动切换模式。烟雾、燃气、进水、紧急按钮和防拆在所有模式下始终监控，编辑本身不会布防。只有管理员可以保存。",
        "Quando o servidor tem os modos de armar, o painel lateral ganha um separador Modos. Ausente defende tudo; para Em casa e Noite, assinala as zonas, sensores, nós de radar e câmaras que cada um defende e ajusta os atrasos de saída e de entrada. Um horário pode mudar o modo sozinho a uma hora do dia. Fumo, gás, inundação, pânico e sabotagem vigiam em todos os modos, e editar não arma nada. Só um administrador guarda."] },
    { target: "ad-side", placement: "left",
      t: ["Properties, ties to the real panels and checks", "Propiedades, vínculos con centrales reales y comprobaciones", "Eigenschaften, Verknüpfung mit echten Zentralen und Prüfungen", "Propriétés, liens avec les vraies centrales et contrôles", "Proprietà, legami con le centrali reali e controlli", "プロパティ・実機との紐付け・チェック", "属性、与真实主机的关联及检查", "Propriedades, ligação às centrais reais e verificações"],
      b: ["The side panel has the properties of the selection and the list of checks. Tie a drawn panel to a real one, and a drawn sensor to one of its zones: the element then shows live what the panel says (green normal, red when the zone is open or the panel sounds, grey when the panel stopped reporting), and \"Open the Alarm panels menu\" takes you to the real panel. The checks warn of a sensor nobody listens to, a panel with no siren, keypad or backup battery, a wireless sensor with no battery type and a smoke or flood sensor silent while disarmed. It is a guide, not proof of protection; nothing here arms or sounds anything.",
        "El panel lateral tiene las propiedades de la selección y la lista de comprobaciones. Liga una central dibujada con una real, y un sensor dibujado con una de sus zonas: el elemento muestra entonces en vivo lo que dice la central (verde normal, rojo con la zona abierta o la central sonando, gris si la central dejó de informar), y \"Abrir el menú Centrales de alarma\" te lleva a la central real. Las comprobaciones avisan de un sensor que nadie escucha, una central sin sirena, teclado o batería de respaldo, un sensor inalámbrico sin tipo de pila y un sensor de humo o inundación que callaría desarmado. Es una guía, no una prueba de protección; nada aquí arma ni hace sonar nada.",
        "Das Seitenfeld enthält die Eigenschaften der Auswahl und die Liste der Prüfungen. Verknüpfen Sie eine gezeichnete Zentrale mit einer echten und einen gezeichneten Sensor mit einer ihrer Zonen: Das Element zeigt dann live, was die Zentrale meldet (grün normal, rot bei offener Zone oder heulender Zentrale, grau wenn die Zentrale nicht mehr berichtet), und \"Menü Alarmzentralen öffnen\" führt zur echten Zentrale. Die Prüfungen warnen vor einem Sensor, den niemand hört, einer Zentrale ohne Sirene, Bedienteil oder Notakku, einem Funksensor ohne Batterietyp und einem Rauch- oder Wassermelder, der unscharf schweigen würde. Es ist ein Leitfaden, kein Schutznachweis; nichts hier schaltet scharf oder löst aus.",
        "Le panneau latéral contient les propriétés de la sélection et la liste des contrôles. Liez une centrale dessinée à une vraie, et un capteur dessiné à l'une de ses zones : l'élément montre alors en direct ce que dit la centrale (vert normal, rouge quand la zone est ouverte ou la centrale sonne, gris quand elle ne rapporte plus), et « Ouvrir le menu Centrales d'alarme » mène à la vraie centrale. Les contrôles signalent un capteur que personne n'écoute, une centrale sans sirène, clavier ou batterie de secours, un capteur sans fil sans type de pile et un détecteur de fumée ou d'inondation muet quand c'est désarmé. C'est un guide, pas une preuve de protection ; rien ici n'arme ni ne fait sonner quoi que ce soit.",
        "Il pannello laterale ha le proprietà della selezione e l'elenco dei controlli. Lega una centrale disegnata a una vera, e un sensore disegnato a una sua zona: l'elemento mostra allora dal vivo ciò che dice la centrale (verde normale, rosso con la zona aperta o la centrale che suona, grigio se la centrale ha smesso di riferire), e \"Apri il menu Centrali di allarme\" porta alla centrale vera. I controlli avvisano di un sensore che nessuno ascolta, una centrale senza sirena, tastiera o batteria di riserva, un sensore wireless senza tipo di pila e un sensore di fumo o allagamento che tacerebbe a sistema disinserito. È una guida, non una prova di protezione; nulla qui inserisce né fa suonare nulla.",
        "サイドパネルには選択物のプロパティとチェック一覧があります。描いた制御盤を実際の制御盤に、描いたセンサーをそのゾーンに紐付けると、要素が制御盤の状態をライブで表示します（緑＝正常、赤＝ゾーン開放または鳴動、灰色＝報告停止）。「警報制御盤メニューを開く」で実機へ移動します。チェックは、誰も聞いていないセンサー、サイレン・キーパッド・バックアップ電池のない制御盤、電池種別のない無線センサー、解除中は鳴らない煙・浸水センサーを警告します。保護を保証するものではなく、ここから警戒やサイレン鳴動は行われません。",
        "侧面板包含所选内容的属性和检查列表。把画出的主机关联到真实主机，把画出的传感器关联到其某个分区：该元件就会实时显示主机的状态（绿色正常，分区打开或主机鸣响时红色，主机停止上报时灰色），“打开报警主机菜单”可跳到真实主机。检查会提醒：无人监听的传感器、没有警笛、键盘或备用电池的主机、未设置电池类型的无线传感器，以及撤防时会沉默的烟雾或水浸传感器。这只是参考，不是防护证明；这里的任何操作都不会布防或使其鸣响。",
        "O painel lateral tem as propriedades da seleção e a lista de verificações. Ligue uma central desenhada a uma real, e um sensor desenhado a uma das suas zonas: o elemento mostra então em direto o que a central diz (verde normal, vermelho com a zona aberta ou a central a tocar, cinzento se a central deixou de comunicar), e \"Abrir o menu Centrais de alarme\" leva à central real. As verificações avisam de um sensor que ninguém escuta, uma central sem sirene, teclado ou bateria de reserva, um sensor sem fios sem tipo de pilha e um sensor de fumo ou inundação que ficaria mudo desarmado. É um guia, não uma prova de proteção; nada aqui arma nem faz soar nada."] },
  ],
  electricalDesigner: [
    { target: "ed-palette", placement: "right",
      t: ["The palette of the installation", "La paleta de la instalación", "Die Palette der Anlage", "La palette de l'installation", "La tavolozza dell'impianto", "設備パレット", "电气元件库", "A paleta da instalação"],
      b: ["Draw the electrical installation as a diagram: the grid, panels, breakers, meters, solar panels, inverters, batteries, loads and the wires between them. Pick an element in the palette and click on the drawing to place it (Shift keeps placing, Esc cancels). \"Load the example\" brings a house with solar to start from. \"Draw the motors and water equipment of the site\" adds, once, every motor, water heater and pump drawn in the Site designer as loads.",
        "Dibuja la instalación eléctrica como un esquema: la red, cuadros, automáticos, contadores, paneles solares, inversores, baterías, cargas y los cables entre ellos. Elige un elemento en la paleta y haz clic en el dibujo para colocarlo (Mayús sigue colocando, Esc cancela). \"Cargar el ejemplo\" trae una casa con solar para empezar. \"Dibujar los motores y equipos de agua del sitio\" añade, una vez, cada motor, calentador y bomba dibujados en el Diseñador de emplazamiento como cargas.",
        "Zeichnen Sie die Elektroanlage als Schaltplan: Netz, Verteiler, Schutzschalter, Zähler, Solarmodule, Wechselrichter, Batterien, Lasten und die Leitungen dazwischen. Wählen Sie ein Element in der Palette und klicken Sie in die Zeichnung, um es zu platzieren (Umschalt platziert weiter, Esc bricht ab). \"Beispiel laden\" bringt ein Haus mit Solar als Start. \"Motoren und Wassergeräte des Standorts zeichnen\" fügt einmalig jeden im Standort-Designer gezeichneten Motor, Warmwasserbereiter und jede Pumpe als Last hinzu.",
        "Dessinez l'installation électrique sous forme de schéma : le réseau, tableaux, disjoncteurs, compteurs, panneaux solaires, onduleurs, batteries, charges et les fils entre eux. Choisissez un élément dans la palette et cliquez dans le dessin pour le placer (Maj continue à placer, Échap annule). « Charger l'exemple » apporte une maison avec solaire pour démarrer. « Dessiner les moteurs et équipements d'eau du site » ajoute, une fois, chaque moteur, chauffe-eau et pompe dessinés dans le concepteur de site comme charges.",
        "Disegna l'impianto elettrico come schema: la rete, quadri, interruttori, contatori, pannelli solari, inverter, batterie, carichi e i fili tra loro. Scegli un elemento nella tavolozza e clicca sul disegno per posizionarlo (Maiusc continua a posizionare, Esc annulla). \"Carica l'esempio\" porta una casa con solare da cui partire. \"Disegna i motori e le apparecchiature idriche del sito\" aggiunge, una volta, ogni motore, scaldabagno e pompa disegnati nel progettista del sito come carichi.",
        "設備を回路図として描きます：系統、分電盤、ブレーカー、メーター、太陽光パネル、インバーター、バッテリー、負荷とそれらを結ぶ配線。パレットで要素を選んで図面をクリックして配置します（Shiftで連続配置、Escで取消）。「例を読み込む」で太陽光付きの家から始められます。「サイトのモーターと水まわり機器を描く」で、サイト設計で描いたモーター・給湯器・ポンプを負荷として1回だけ追加します。",
        "把电气设施画成线路图：电网、配电箱、断路器、电表、太阳能板、逆变器、电池、负载以及它们之间的导线。在元件库选一个元件，点击图纸放置（按住 Shift 可连续放置，Esc 取消）。“载入示例”提供一栋带太阳能的住宅作为起点。“绘制场地的电机和水设备”会一次性把场地设计器里画的所有电机、热水器和水泵作为负载添加进来。",
        "Desenhe a instalação elétrica como um esquema: a rede, quadros, disjuntores, contadores, painéis solares, inversores, baterias, cargas e os fios entre eles. Escolha um elemento na paleta e clique no desenho para o colocar (Maiús continua a colocar, Esc cancela). \"Carregar o exemplo\" traz uma casa com solar para começar. \"Desenhar os motores e equipamentos de água do local\" acrescenta, uma vez, cada motor, esquentador e bomba desenhados no Desenhador do local como cargas."] },
    { target: "ed-canvas", placement: "left",
      t: ["Wires: label, length and cross-section", "Cables: etiqueta, longitud y sección", "Leitungen: Beschriftung, Länge, Querschnitt", "Fils : étiquette, longueur et section", "Fili: etichetta, lunghezza e sezione", "配線：ラベル・長さ・断面積", "导线：标签、长度与截面", "Fios: etiqueta, comprimento e secção"],
      b: ["With the Wire tool, click one port and then another to join them. A wire has a label, a length in metres and a cross-section in square millimetres, and the checks use the last two to judge the voltage drop and the current it can carry: a wire left at the default is the usual cause of a warning. The Frame tool draws a frame around the elements of one panel. Select moves and edits; the inspector shows the properties of the selection, including whether a switch is drawn open or closed.",
        "Con la herramienta Cable, haz clic en un puerto y luego en otro para unirlos. Un cable tiene etiqueta, longitud en metros y sección en milímetros cuadrados, y las comprobaciones usan las dos últimas para juzgar la caída de tensión y la corriente que aguanta: un cable dejado con el valor por defecto es la causa habitual de un aviso. La herramienta Marco dibuja un marco alrededor de los elementos de un cuadro. Seleccionar mueve y edita; el inspector muestra las propiedades de la selección, incluido si un interruptor se dibuja abierto o cerrado.",
        "Mit dem Leitungswerkzeug klicken Sie erst einen Port, dann einen anderen an. Eine Leitung hat eine Beschriftung, eine Länge in Metern und einen Querschnitt in Quadratmillimetern; die Prüfungen nutzen die beiden letzten, um Spannungsabfall und Strombelastbarkeit zu beurteilen: Eine Leitung mit Standardwerten ist die übliche Ursache einer Warnung. Das Rahmenwerkzeug zeichnet einen Rahmen um die Elemente eines Verteilers. Auswählen verschiebt und bearbeitet; der Inspektor zeigt die Eigenschaften, auch ob ein Schalter offen oder geschlossen gezeichnet ist.",
        "Avec l'outil Fil, cliquez sur un port puis sur un autre pour les joindre. Un fil a une étiquette, une longueur en mètres et une section en millimètres carrés ; les contrôles utilisent les deux dernières pour juger la chute de tension et le courant admissible : un fil laissé aux valeurs par défaut est la cause habituelle d'un avertissement. L'outil Cadre dessine un cadre autour des éléments d'un tableau. Sélection déplace et modifie ; l'inspecteur montre les propriétés, y compris si un interrupteur est dessiné ouvert ou fermé.",
        "Con lo strumento Filo, clicca su una porta e poi su un'altra per unirle. Un filo ha un'etichetta, una lunghezza in metri e una sezione in millimetri quadrati; i controlli usano le ultime due per giudicare la caduta di tensione e la corrente sopportata: un filo lasciato ai valori predefiniti è la causa abituale di un avviso. Lo strumento Riquadro disegna un riquadro attorno agli elementi di un quadro. Seleziona sposta e modifica; l'ispettore mostra le proprietà, anche se un interruttore è disegnato aperto o chiuso.",
        "配線ツールで、1つのポートをクリックしてから別のポートをクリックすると接続されます。配線にはラベル、長さ（m）、断面積（mm²）があり、チェックは後ろの2つで電圧降下と許容電流を判断します。初期値のままの配線が、警告の典型的な原因です。フレームツールは1つの分電盤の要素を枠で囲みます。選択は移動と編集、インスペクターは選択物のプロパティ（スイッチを開／閉どちらで描くかも含む）を表示します。",
        "使用导线工具，先点一个端口再点另一个即可连接。导线有标签、以米计的长度和以平方毫米计的截面，检查会用后两项判断压降和载流能力：导线保持默认值是警告最常见的原因。框工具会在一个配电箱的元件周围画框。选择工具用于移动和编辑；检查器显示所选内容的属性，包括开关画成断开还是闭合。",
        "Com a ferramenta Fio, clique numa porta e depois noutra para as unir. Um fio tem uma etiqueta, um comprimento em metros e uma secção em milímetros quadrados, e as verificações usam os dois últimos para avaliar a queda de tensão e a corrente suportada: um fio deixado com o valor por defeito é a causa habitual de um aviso. A ferramenta Moldura desenha uma moldura à volta dos elementos de um quadro. Selecionar move e edita; o inspetor mostra as propriedades, incluindo se um interruptor é desenhado aberto ou fechado."] },
    { target: "ed-side", placement: "left",
      t: ["The checks and the live binding", "Las comprobaciones y el vínculo en vivo", "Die Prüfungen und die Live-Verknüpfung", "Les contrôles et le lien en direct", "I controlli e il legame dal vivo", "チェックとライブ連携", "检查与实时绑定", "As verificações e a ligação em direto"],
      b: ["The \"Checks\" tab reviews the drawing and lists errors and warnings; click one to jump to the element. It is a guide for reviewing the drawing, not a substitute for an electrician or the regulations. An element can be bound to the electrical node that measures it or to a solar device it shows, so the Electrical menu draws the live values on the diagram. Nothing here switches or measures anything by itself.",
        "La pestaña \"Comprobaciones\" revisa el dibujo y lista errores y avisos; haz clic en uno para saltar al elemento. Es una guía para revisar el dibujo, no un sustituto de un electricista ni de la normativa. Un elemento puede ligarse al nodo eléctrico que lo mide o a un dispositivo solar que muestra, de modo que el menú Eléctrico dibuje los valores en vivo sobre el esquema. Nada aquí conmuta ni mide nada por sí mismo.",
        "Der Reiter \"Prüfungen\" prüft die Zeichnung und listet Fehler und Warnungen; ein Klick springt zum Element. Er ist eine Hilfe zur Durchsicht, kein Ersatz für einen Elektriker oder die Vorschriften. Ein Element lässt sich an den Elektroknoten binden, der es misst, oder an ein Solargerät, das es zeigt, sodass das Menü Elektrik die Live-Werte auf den Plan zeichnet. Nichts hier schaltet oder misst von selbst.",
        "L'onglet « Contrôles » examine le dessin et liste erreurs et avertissements ; cliquez sur l'un pour aller à l'élément. C'est un guide pour relire le dessin, pas un substitut à un électricien ni à la réglementation. Un élément peut être lié au nœud électrique qui le mesure ou à un appareil solaire qu'il montre, de sorte que le menu Électrique dessine les valeurs en direct sur le schéma. Rien ici ne commute ni ne mesure de lui-même.",
        "La scheda \"Controlli\" esamina il disegno ed elenca errori e avvisi; clicca su uno per saltare all'elemento. È una guida per rivedere il disegno, non un sostituto di un elettricista né delle norme. Un elemento può essere legato al nodo elettrico che lo misura o a un dispositivo solare che mostra, così il menu Elettrico disegna i valori dal vivo sullo schema. Nulla qui commuta né misura da solo.",
        "「チェック」タブは図面を点検してエラーと警告を一覧にし、クリックで該当要素へジャンプします。図面を見直すための目安であり、電気工事士や法規の代わりにはなりません。要素を、それを計測する電気ノードや、表示する太陽光機器に紐付けると、「電気」メニューが図の上にライブ値を描きます。ここから切替や計測が行われることはありません。",
        "“检查”标签页会审查图纸并列出错误和警告，点击某一项可跳到对应元件。它只是复查图纸的参考，不能替代电工或法规。元件可绑定到测量它的电气节点或它所显示的太阳能设备，这样“电气”菜单就会把实时数值画在图上。这里的任何内容本身都不会切换或测量任何东西。",
        "O separador \"Verificações\" revê o desenho e lista erros e avisos; clique num para saltar ao elemento. É um guia para rever o desenho, não um substituto de um eletricista nem da regulamentação. Um elemento pode ligar-se ao nó elétrico que o mede ou a um dispositivo solar que mostra, para que o menu Elétrico desenhe os valores em direto sobre o esquema. Nada aqui comuta nem mede nada por si."] },
    { target: "ed-toolbar", placement: "bottom",
      t: ["Files, versions and a new drawing", "Archivos, versiones y un dibujo nuevo", "Dateien, Versionen und eine neue Zeichnung", "Fichiers, versions et nouveau dessin", "File, versioni e un nuovo disegno", "ファイル・バージョン・新規図面", "文件、版本与新建图纸", "Ficheiros, versões e um desenho novo"],
      b: ["Export JSON saves the drawing as a file, Export SVG makes an image you can print, Import JSON loads one and New drawing starts an empty one (Studio asks before replacing what you have). The server keeps the earlier versions of the drawing and you can go back to one with Versions. Undo and redo walk through your changes, and the fit button centres the drawing in view.",
        "Exportar JSON guarda el dibujo como archivo, Exportar SVG genera una imagen que puedes imprimir, Importar JSON carga uno y Nuevo dibujo empieza uno vacío (Studio pregunta antes de reemplazar lo que tienes). El servidor guarda las versiones anteriores del dibujo y puedes volver a una con Versiones. Deshacer y rehacer recorren tus cambios, y el botón de encajar centra el dibujo en la vista.",
        "JSON exportieren speichert die Zeichnung als Datei, SVG exportieren erzeugt ein druckbares Bild, JSON importieren lädt eine, und Neue Zeichnung beginnt eine leere (Studio fragt vor dem Ersetzen). Der Server hält frühere Versionen, zu denen Sie mit Versionen zurückkehren. Rückgängig und Wiederholen gehen durch Ihre Änderungen, die Einpass-Taste zentriert die Zeichnung.",
        "Exporter JSON enregistre le dessin en fichier, Exporter SVG produit une image imprimable, Importer JSON en charge un et Nouveau dessin en démarre un vide (Studio demande avant de remplacer). Le serveur garde les versions antérieures du dessin et vous pouvez revenir à l'une avec Versions. Annuler et rétablir parcourent vos changements, et le bouton d'ajustement centre le dessin.",
        "Esporta JSON salva il disegno come file, Esporta SVG crea un'immagine stampabile, Importa JSON ne carica uno e Nuovo disegno ne inizia uno vuoto (Studio chiede prima di sostituire). Il server conserva le versioni precedenti e puoi tornare a una con Versioni. Annulla e ripeti ripercorrono le modifiche, e il pulsante di adattamento centra il disegno.",
        "「JSONを書き出す」で図面をファイルに保存、「SVGを書き出す」で印刷できる画像、「JSONを読み込む」で取り込み、「新規図面」で空の図面を始めます（置き換え前にStudioが確認）。サーバーが過去のバージョンを保持し、「バージョン」から戻せます。元に戻す／やり直しで変更を行き来でき、フィットボタンで図面を表示の中央に戻します。",
        "“导出 JSON”把图纸保存为文件，“导出 SVG”生成可打印的图片，“导入 JSON”载入一份，“新建图纸”开始空白图（替换前 Studio 会询问）。服务器会保存图纸的历史版本，可用“版本”回到其中一个。撤销和重做可在修改间来回，适应按钮让图纸居中。",
        "Exportar JSON guarda o desenho como ficheiro, Exportar SVG gera uma imagem que pode imprimir, Importar JSON carrega um e Novo desenho começa um vazio (o Studio pergunta antes de substituir). O servidor guarda as versões anteriores e pode voltar a uma com Versões. Desfazer e refazer percorrem as alterações, e o botão de ajustar centra o desenho na vista."] },
  ],
  networkDesigner: [
    { target: "nd-palette", placement: "right",
      t: ["The devices of the network", "Los dispositivos de la red", "Die Geräte des Netzes", "Les appareils du réseau", "I dispositivi della rete", "ネットワークの機器", "网络设备", "Os dispositivos da rede"],
      b: ["Draw the network of the house or the site: the operator's line, the router, switches, access points, cameras, nodes, computers and the cables between them. Pick a device in the palette and click to place it; Rotate (R) turns it and \"Replace with another device\" swaps it for another and keeps its cables. \"Typical house\" loads an example to start from. Name every device as you place it: the checks and the list of what is missing are much easier to read.",
        "Dibuja la red de la casa o del sitio: la línea del operador, el router, conmutadores, puntos de acceso, cámaras, nodos, ordenadores y los cables entre ellos. Elige un dispositivo en la paleta y haz clic para colocarlo; Girar (R) lo gira y \"Sustituir por otro dispositivo\" lo cambia por otro conservando sus cables. \"Casa típica\" carga un ejemplo para empezar. Pon nombre a cada dispositivo al colocarlo: las comprobaciones y la lista de lo que falta se leen mucho mejor.",
        "Zeichnen Sie das Netz des Hauses oder Standorts: die Leitung des Anbieters, Router, Switches, Zugangspunkte, Kameras, Knoten, Computer und die Kabel dazwischen. Wählen Sie ein Gerät in der Palette und klicken Sie zum Platzieren; Drehen (R) dreht es, \"Durch anderes Gerät ersetzen\" tauscht es und behält die Kabel. \"Typisches Haus\" lädt ein Beispiel. Benennen Sie jedes Gerät beim Platzieren: Prüfungen und die Liste des Fehlenden lesen sich viel besser.",
        "Dessinez le réseau de la maison ou du site : la ligne de l'opérateur, le routeur, les commutateurs, points d'accès, caméras, nœuds, ordinateurs et les câbles entre eux. Choisissez un appareil dans la palette et cliquez pour le placer ; Pivoter (R) le tourne et « Remplacer par un autre appareil » l'échange en gardant ses câbles. « Maison type » charge un exemple. Nommez chaque appareil en le plaçant : les contrôles et la liste de ce qui manque se lisent bien mieux.",
        "Disegna la rete della casa o del sito: la linea dell'operatore, il router, gli switch, i punti di accesso, le telecamere, i nodi, i computer e i cavi tra loro. Scegli un dispositivo nella tavolozza e clicca per posizionarlo; Ruota (R) lo gira e \"Sostituisci con un altro dispositivo\" lo scambia mantenendo i cavi. \"Casa tipica\" carica un esempio. Dai un nome a ogni dispositivo quando lo posizioni: i controlli e l'elenco di ciò che manca si leggono molto meglio.",
        "家やサイトのネットワークを描きます：回線事業者の回線、ルーター、スイッチ、アクセスポイント、カメラ、ノード、パソコン、そしてケーブル。パレットから機器を選んでクリックで配置します。回転（R）で向きを変え、「別の機器に置き換え」でケーブルを保ったまま入れ替えます。「典型的な家」で例を読み込めます。配置時に機器へ名前を付けると、チェックや不足一覧が格段に読みやすくなります。",
        "绘制住宅或场地的网络：运营商线路、路由器、交换机、接入点、摄像头、节点、电脑以及它们之间的线缆。在元件库选择设备，点击放置；旋转（R）转动设备，“替换为其他设备”会换成另一种并保留线缆。“典型住宅”载入示例。放置时给每个设备命名：检查结果和缺失清单会更容易阅读。",
        "Desenhe a rede da casa ou do local: a linha do operador, o router, comutadores, pontos de acesso, câmaras, nós, computadores e os cabos entre eles. Escolha um dispositivo na paleta e clique para o colocar; Rodar (R) roda-o e \"Substituir por outro dispositivo\" troca-o por outro mantendo os cabos. \"Casa típica\" carrega um exemplo. Dê nome a cada dispositivo ao colocá-lo: as verificações e a lista do que falta leem-se muito melhor."] },
    { target: "nd-canvas", placement: "left",
      t: ["Links: speed and VLAN", "Enlaces: velocidad y VLAN", "Verbindungen: Geschwindigkeit und VLAN", "Liaisons : débit et VLAN", "Collegamenti: velocità e VLAN", "リンク：速度とVLAN", "连线：速率与 VLAN", "Ligações: velocidade e VLAN"],
      b: ["With the Link tool, click one device and then the other to join them. A link can have a speed in Mbit/s and a VLAN, and the checks use them to warn of things like a camera on a slow link or a cable that ends nowhere. The Frame tool groups the devices of a room or a floor. Select moves and edits, and the inspector shows the properties of what you selected. Drawing a link does not configure the real switch or router: it is only a drawing.",
        "Con la herramienta Enlace, haz clic en un dispositivo y luego en el otro para unirlos. Un enlace puede tener velocidad en Mbit/s y una VLAN, y las comprobaciones los usan para avisar de cosas como una cámara en un enlace lento o un cable que no acaba en ninguna parte. La herramienta Marco agrupa los dispositivos de una habitación o planta. Seleccionar mueve y edita, y el inspector muestra las propiedades de lo seleccionado. Dibujar un enlace no configura el conmutador ni el router reales: es solo un dibujo.",
        "Mit dem Verbindungswerkzeug klicken Sie erst ein Gerät, dann das andere an. Eine Verbindung kann eine Geschwindigkeit in Mbit/s und ein VLAN haben; die Prüfungen nutzen sie, um zum Beispiel vor einer Kamera an einer langsamen Verbindung oder einem Kabel ohne Ziel zu warnen. Das Rahmenwerkzeug gruppiert die Geräte eines Raums oder einer Etage. Auswählen verschiebt und bearbeitet, der Inspektor zeigt die Eigenschaften. Eine Verbindung zu zeichnen konfiguriert den echten Switch oder Router nicht: Es ist nur eine Zeichnung.",
        "Avec l'outil Liaison, cliquez sur un appareil puis sur l'autre pour les joindre. Une liaison peut avoir un débit en Mbit/s et un VLAN, et les contrôles s'en servent pour signaler par exemple une caméra sur une liaison lente ou un câble qui ne mène nulle part. L'outil Cadre regroupe les appareils d'une pièce ou d'un étage. Sélection déplace et modifie, et l'inspecteur montre les propriétés. Dessiner une liaison ne configure pas le vrai commutateur ni routeur : ce n'est qu'un dessin.",
        "Con lo strumento Collegamento, clicca su un dispositivo e poi sull'altro per unirli. Un collegamento può avere una velocità in Mbit/s e una VLAN, e i controlli li usano per avvisare, per esempio, di una telecamera su un collegamento lento o di un cavo che non finisce da nessuna parte. Lo strumento Riquadro raggruppa i dispositivi di una stanza o di un piano. Seleziona sposta e modifica, e l'ispettore mostra le proprietà. Disegnare un collegamento non configura lo switch o il router reali: è solo un disegno.",
        "リンクツールで、機器を1つクリックしてからもう1つをクリックすると接続されます。リンクには速度（Mbit/s）とVLANを設定でき、チェックはそれを使って、遅い回線につながったカメラや行き先のないケーブルなどを警告します。フレームツールは部屋や階の機器をまとめます。選択は移動と編集、インスペクターはプロパティを表示します。リンクを描いても実際のスイッチやルーターは設定されません。あくまで図面です。",
        "使用连线工具，先点一台设备再点另一台即可连接。连线可设置速率（Mbit/s）和 VLAN，检查会据此提醒诸如摄像头接在慢速链路上、线缆没有终点等问题。框工具用于把一个房间或楼层的设备分组。选择工具用于移动和编辑，检查器显示所选内容的属性。画连线并不会配置真实的交换机或路由器：这只是一张图。",
        "Com a ferramenta Ligação, clique num dispositivo e depois no outro para os unir. Uma ligação pode ter uma velocidade em Mbit/s e uma VLAN, e as verificações usam-nas para avisar, por exemplo, de uma câmara numa ligação lenta ou de um cabo que não acaba em lado nenhum. A ferramenta Moldura agrupa os dispositivos de uma divisão ou piso. Selecionar move e edita, e o inspetor mostra as propriedades. Desenhar uma ligação não configura o comutador ou o router reais: é só um desenho."] },
    { target: "nd-toolbar", placement: "bottom",
      t: ["Draw what was found, and tie it to the real", "Dibujar lo encontrado y ligarlo a lo real", "Gefundenes zeichnen und mit dem Echten verknüpfen", "Dessiner ce qui a été trouvé et le lier au réel", "Disegnare ciò che è stato trovato e legarlo al reale", "検出結果を描いて実物に紐付ける", "绘制发现的设备并与真实设备关联", "Desenhar o que foi encontrado e ligá-lo ao real"],
      b: ["\"Draw what was found\" puts on the plan the devices that the network node discovered and are not yet drawn; a drawn device can be tied to the real device found, and a drawn camera to a camera of the Cameras menu. With ties, the drawing can tell you what is drawn and not found, and what is found and not drawn. Files: export the drawing as JSON or SVG and import one; the server keeps the earlier versions.",
        "\"Dibujar lo encontrado\" coloca en el plano los dispositivos que el nodo de red descubrió y que aún no están dibujados; un dispositivo dibujado se puede ligar al dispositivo real encontrado, y una cámara dibujada a una cámara del menú Cámaras. Con los vínculos, el dibujo puede decirte qué está dibujado y no encontrado, y qué está encontrado y no dibujado. Archivos: exporta el dibujo como JSON o SVG e importa uno; el servidor guarda las versiones anteriores.",
        "\"Gefundenes zeichnen\" setzt die vom Netzwerkknoten entdeckten, noch nicht gezeichneten Geräte in den Plan; ein gezeichnetes Gerät lässt sich mit dem gefundenen echten Gerät verknüpfen, eine gezeichnete Kamera mit einer Kamera des Menüs Kameras. Mit den Verknüpfungen sagt die Zeichnung, was gezeichnet, aber nicht gefunden ist und was gefunden, aber nicht gezeichnet. Dateien: Zeichnung als JSON oder SVG exportieren und importieren; der Server hält frühere Versionen.",
        "« Dessiner ce qui a été trouvé » place sur le plan les appareils que le nœud réseau a découverts et qui ne sont pas encore dessinés ; un appareil dessiné peut être lié à l'appareil réel trouvé, et une caméra dessinée à une caméra du menu Caméras. Avec les liens, le dessin dit ce qui est dessiné mais pas trouvé, et ce qui est trouvé mais pas dessiné. Fichiers : exporter le dessin en JSON ou SVG et en importer un ; le serveur garde les versions antérieures.",
        "\"Disegna ciò che è stato trovato\" mette sulla pianta i dispositivi scoperti dal nodo di rete e non ancora disegnati; un dispositivo disegnato si può legare al dispositivo reale trovato, e una telecamera disegnata a una telecamera del menu Telecamere. Con i legami, il disegno può dirti cosa è disegnato e non trovato, e cosa è trovato e non disegnato. File: esporta il disegno in JSON o SVG e importane uno; il server conserva le versioni precedenti.",
        "「検出結果を描く」は、ネットワークノードが見つけたがまだ描かれていない機器を図面に追加します。描いた機器は見つかった実機に、描いたカメラは「カメラ」メニューのカメラに紐付けられます。紐付けがあると、「描いたのに見つからない機器」と「見つかったのに描いていない機器」が分かります。ファイル：JSONまたはSVGで書き出し・取り込みができ、サーバーが過去のバージョンを保持します。",
        "“绘制发现的设备”会把网络节点发现但尚未画出的设备放到图上；画出的设备可与发现的真实设备关联，画出的摄像头可与“摄像头”菜单中的摄像头关联。有了关联，图纸就能告诉你哪些画了却没发现，哪些发现了却没画。文件：把图导出为 JSON 或 SVG，也可导入；服务器保留历史版本。",
        "\"Desenhar o que foi encontrado\" põe na planta os dispositivos que o nó de rede descobriu e que ainda não estão desenhados; um dispositivo desenhado pode ligar-se ao dispositivo real encontrado, e uma câmara desenhada a uma câmara do menu Câmaras. Com as ligações, o desenho pode dizer-lhe o que está desenhado e não foi encontrado, e o que foi encontrado e não está desenhado. Ficheiros: exporte o desenho em JSON ou SVG e importe um; o servidor guarda as versões anteriores."] },
  ],
};
